sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var intakeId = current.intake_case + '';
    if (!intakeId)
        return;

    var intake = new GlideRecord('x_gegis_ins_policy_intake_case');
    if (!intake.get(intakeId))
        return;

    var verb = current.active.changesTo(false) ? 'closed' : 'updated';
    intake.work_notes = 'HITL task ' + current.number +
        ' (' + current.getDisplayValue('u_type') + ') ' + verb + '.' +
        '\nTask state: ' + current.getDisplayValue('state');
    intake.update();

})(current, previous);
